#include <bits/stdc++.h>
using namespace std;

struct FenwickTree {
    vector<long long> val;
    FenwickTree(size_t n) : val(n + 1, 0) {}
    void add(size_t x, long long v) {
        while (x < val.size()) {
            val[x] += v;
            x += x & (~x + 1);
        }
    }
    long long sum(size_t x) {
        assert(x < val.size());
        long long ans = 0;
        while (x > 0) {
            ans += val[x];
            x -= x & (~x + 1);
        }
        return ans;
    }
};

vector<long long> sieve(size_t n) {
    vector<bool> is_prime(n + 1, true);
    for (size_t i = 2;; ++i) {
        if (i * i > n) break;
        if (is_prime[i]) {
            size_t j = i * i;
            while (j <= n) {
                is_prime[j] = false;
                j += i;
            }
        }
    }
    size_t len = 0;
    for (size_t i = 2; i <= n; ++i) if (is_prime[i]) ++len;
    vector<long long> prime;
    prime.reserve(len);
    for (size_t i = 2; i <= n; ++i) {
        if (is_prime[i]) prime.push_back((long long)i);
    }
    return prime;
}

struct PrimeCountSolver {
    vector<long long> query;
    vector<long long> memo;
    PrimeCountSolver() {}
    void add(long long n) {
        query.push_back(n);
    }
    void build() {
        sort(query.begin(), query.end());
        query.erase(unique(query.begin(), query.end()), query.end());
        long long n = query.empty() ? 1 : query.back();
        long long m = 1;
        while ((m + 1) * (m + 1) <= n) ++m;
        vector<long long> p = sieve((size_t)m);
        long long bound = (long long)(pow(cbrt((double)n), 2.0)) + 2;
        vector<pair<long long,int>> stack;
        for (auto v : query) {
            int k;
            auto it = lower_bound(p.begin(), p.end(), 0LL, [v](long long pp, long long){
                long long sq = pp * pp;
                if (sq < v) return false;
                return false;
            });
            int left = 0, right = (int)p.size();
            while (left < right) {
                int mid = (left + right) / 2;
                long long sq = p[mid] * p[mid];
                if (sq < v) left = mid + 1;
                else right = mid;
            }
            if (left < (int)p.size() && p[left] * p[left] == v) k = left + 1;
            else k = left;
            stack.emplace_back(v, k);
        }
        vector<pair<int,long long>> query2;
        while (!stack.empty()) {
            auto [nn, k] = stack.back(); stack.pop_back();
            if (k == 0) continue;
            long long q = p[k - 1];
            if (q * q > nn) {
                int x;
                int left = 0, right = k;
