                    int mid = (left + right) / 2;
                    long long sq = p[mid] * p[mid];
                    if (sq < nn) left = mid + 1;
                    else right = mid;
                }
                if (left < k && p[left] * p[left] == nn) x = left + 1;
                else x = left;
                stack.emplace_back(nn, x);
            } else if (nn <= bound) {
                query2.emplace_back(k, nn);
            } else {
                stack.emplace_back(nn, k - 1);
                stack.emplace_back(nn / q, k - 1);
            }
        }
        sort(query2.begin(), query2.end());
        query2.erase(unique(query2.begin(), query2.end()), query2.end());
        size_t mm = (size_t)bound;
        FenwickTree bit(mm);
        for (size_t i = 1; i <= mm; ++i) bit.add(i, 1);
        vector<bool> is_prime(mm + 1, true);
        vector<long long> memo2(query2.size(), 0);
        size_t pos = 0;
