            }
            if (pos >= query2.size()) break;
        }
        memo.assign(query.size(), 0);
        vector<tuple<long long,int,long long,int>> stack2;
        for (size_t i = 0; i < query.size(); ++i) {
            long long nn = query[i];
            int k;
            int left = 0, right = (int)p.size();
            while (left < right) {
                int mid = (left + right) / 2;
                long long sq = p[mid] * p[mid];
                if (sq < nn) left = mid + 1;
                else right = mid;
            }
            if (left < (int)p.size() && p[left] * p[left] == nn) k = left + 1;
            else k = left;
            memo[i] += (long long)k - 1;
            stack2.emplace_back(nn, k, 1LL, (int)i);
        }
        while (!stack2.empty()) {
            auto [nn, k, sign, idx] = stack2.back(); stack2.pop_back();
            if (k == 0) {
