                    if (sq < nn) left = mid + 1;
                    else right = mid;
                }
                if (left < k && p[left] * p[left] == nn) x = left + 1;
                else x = left;
                memo[idx] += -sign * (long long)(k - x);
                stack2.emplace_back(nn, x, sign, idx);
            } else if (nn <= bound) {
                auto it = lower_bound(query2.begin(), query2.end(), make_pair(k, nn));
                int pos2 = (int)(it - query2.begin());
