        }
        vector<tuple<long long, size_t, long long, size_t>> st2;
        for (size_t i = 0; i < query.size(); ++i) {
            long long nn = query[i];
            auto it = lower_bound(p.begin(), p.end(), 0LL, [nn](long long pp, long long) {
                return pp * pp < nn;
            });
            size_t k = it - p.begin();
            if (it != p.end() && (*it) * (*it) == nn) ++k;
            st2.emplace_back(nn, k, 1LL, i);
        }
        while (!st2.empty()) {
            auto [nn, k, sign, idx] = st2.back();
