        long long m = 1;
        while ((m + 1) * (m + 1) <= nmax) ++m;
        vector<long long> p = sieve((size_t)m);
        long long bound = (long long)pow(cbrt((double)nmax), 2) + 2;
        vector<pair<long long, size_t>> stack;
        for (auto v : query) {
            size_t k;
            auto it = lower_bound(p.begin(), p.end(), 0LL, [v](long long pp, long long) {
                return pp * pp < v;
            });
            k = (size_t)(it - p.begin());
            if (it != p.end() && (*it) * (*it) == v) ++k;
            stack.emplace_back(v, k);
        }
        vector<pair<size_t, long long>> qvec;
        while (!stack.empty()) {
            auto [n, k] = stack.back();
            stack.pop_back();
            if (k == 0) continue;
            long long q = p[k - 1];
            if (q * q > n) {
                size_t x;
                auto it = lower_bound(p.begin(), p.begin() + k, 0LL, [n](long long pp, long long) {
                    return pp * pp < n;
                });
