        qvec.erase(unique(qvec.begin(), qvec.end()), qvec.end());
        size_t mm = (size_t)bound;
        FenwickTree bit(mm);
        for (size_t i = 1; i <= mm; ++i) bit.add(i, 1);
        vector<bool> is_prime(mm + 1, true);
        vector<long long> memo_local(qvec.size(), 0);
