                st.emplace_back(n, k - 1, sign, idx);
                st.emplace_back(n / q, k - 1, -sign, idx);
            }
        }
    }

    long long get(long long n) const {
        auto it = lower_bound(query.begin(), query.end(), n);
        size_t idx = (size_t)(it - query.begin());
        return memo[idx];
    }
};

void run() {
    long long n;
